+    tail = "，梦想着" + (dreamNames[dreamId] || dreamId);
+  }
+
+  if (day <= 15) {
+    return (
+      "那时候你刚来这座城市第" +
+      day +
+      "天，在" +
+      loc +
+      "落脚，兜里" +
