+      loc +
+      "打拼了" +
+      day +
+      "天，已经攒下" +
+      Math.round(cash / 1000) +
+      "千元，离梦想越来越近" +
+      tail +
+      "。"
+    );
+  } else {
+    return (
+      "那时候你在城里走过了" +
+      day +
+      "天，在" +
+      loc +
+      "一步一步往前走，手里有¥" +
+      cash.toLocaleString() +
+      tail +
+      "。"
+    );
