1	/**
2	 * 存档系统 — localStorage 多槽位持久化
3	 *
4	 * 5个手动存档槽 + 1个自动存档
5	 * 索引键: 'city_life_story_index' — 存储各槽位元信息
6	 * 存档键: 'city_life_story_slot_N' (N=1..5) + 'city_life_story_autosave'
7	 */
8	
9	const NUM_SLOTS = 5;
10	const SLOT_PREFIX = "city_life_story_slot_";
11	const AUTO_SAVE_KEY = "city_life_story_autosave";
12	const INDEX_KEY = "city_life_story_index";
13	
14	/** 获取槽位键 */
15	function slotKey(n) {
16	  return SLOT_PREFIX + n;
17	}
18	
19	/** 读取存档索引 */
20	function getSaveIndex() {
21	  try {
22	    const raw = localStorage.getItem(INDEX_KEY);
23	    return raw ? JSON.parse(raw) : {};
24	  } catch (e) {
25	    return {};
26	  }
27	}
28	
29	/** 写入存档索引 */
30	function setSaveIndex(index) {
31	  localStorage.setItem(INDEX_KEY, JSON.stringify(index));
32	}
33	
34	/** 生成"那时候你..."回忆文案（存储于索引，读档时展示） */
35	function generateSaveNarrative(state) {
36	  var p = state.player;
37	  var r = state.resources;
38	  var day = p.day;
39	  var cash = (r.cash || 0) + (r.bankBalance || 0);
40	  var debt = r.villageDebt || r.debt || 0;
41	
42	  var locNames = {
43	    slum: "城中村",
44	    wholesaleMarket: "批发市场",
45	    construction: "建筑工地",
46	    factoryZone: "工厂区",
47	    school: "大学城",
48	    commercialDist: "商业区",
49	    techPark: "科技园",
50	    hospital: "医院",
51	    bank: "银行",
52	    park: "公园",
53	    trainingCenter: "培训中心",
54	  };
55	  var loc = locNames[state.trade && state.trade.currentLocation] || "城市某处";
56	
57	  if (p.phase === "corporate") {
58	    var rank = (state.corporate && state.corporate.rank) || "P5";
59	    var company = (state.corporate && state.corporate.company) || "科技公司";
60	    return (
61	      "那时候你已经是" +
62	      company +
63	      "的" +
64	      rank +
65	      "，在职场打拼了" +
66	      day +
67	      "天，存款" +
68	      (cash >= 1000 ? (cash / 1000).toFixed(1) + "万" : "¥" + cash) +
69	      "元。"
70	    );
71	  }
72	
73	  var tail = "";
74	  var dreamId = state.flags && state.flags._dreamId;
75	  if (dreamId) {
76	    var dreamNames = {
77	      restaurant: "开餐馆",
78	      apartment: "买房",
79	      abroad: "出国",
80	      investor: "投资大亨",
81	      celebrity: "城市名人",
82	    };
83	    tail = "，梦想着" + (dreamNames[dreamId] || dreamId);
84	  }
85	
86	  if (day <= 15) {
87	    return (
88	      "那时候你刚来这座城市第" +
89	      day +
90	      "天，在" +
91	      loc +
92	      "落脚，兜里" +
93	      (debt > 0
94	        ? "还欠着¥" + debt.toLocaleString() + "的债"
95	        : "有¥" + cash.toLocaleString()) +
96	      tail +
97	      "。"
98	    );
99	  } else if (cash < 500) {
100	    return (
101	      "那时候你在城里漂了" +
102	      day +
103	      "天，手里只剩¥" +
104	      cash.toLocaleString() +
105	      "，日子过得很紧巴" +
106	      tail +
107	      "。"
108	    );
109	  } else if (cash >= 50000) {
110	    return (
111	      "那时候你在" +
112	      loc +
113	      "打拼了" +
114	      day +
115	      "天，已经攒下" +
116	      Math.round(cash / 1000) +
117	      "千元，离梦想越来越近" +
118	      tail +
119	      "。"
120	    );
121	  } else {
122	    return (
123	      "那时候你在城里走过了" +
124	      day +
125	      "天，在" +
126	      loc +
127	      "一步一步往前走，手里有¥" +
128	      cash.toLocaleString() +
129	      tail +
130	      "。"
131	    );
132	  }
133	}
134	
135	/** 保存游戏到指定槽位（1-5） */
136	function saveGame(slot) {
137	  if (slot < 1 || slot > NUM_SLOTS) {
138	    StateManager.addMessage("⚠️ 无效的存档槽位。", "danger");
139	    return false;
140	  }
141	
142	  try {
143	    const state = StateManager.getState();
144	    state.lastPlayedAt = Date.now();
145	
146	    const saveData = JSON.parse(JSON.stringify(state));
147	    // 精简消息日志
148	    if (saveData.messageLog && saveData.messageLog.length > 200) {
149	      saveData.messageLog = saveData.messageLog.slice(-200);
150	    }
151	
152	    localStorage.setItem(slotKey(slot), JSON.stringify(saveData));
153	
154	    // 更新索引
155	    const index = getSaveIndex();
156	    index[slot] = {
157	      day: state.player.day,
158	      phase: state.player.phase,
159	      cash: state.resources.cash,
160	      age: state.player.age,
161	      debt: state.resources.debt,
162	      totalEarned: state.resources.totalEarned,
163	      location: state.trade.currentLocation,
164	      rank: state.player.phase === "corporate" ? state.corporate.rank : null,
165	      savedAt: Date.now(),
166	      narrative: generateSaveNarrative(state),
167	    };
168	    setSaveIndex(index);
169	
170	    StateManager.addMessage(
171	      `💾 已保存到槽位 ${slot}（第${state.player.day}天，¥${state.resources.cash.toLocaleString()}）`,
172	      "success",
173	    );
174	    return true;
175	  } catch (e) {
176	    console.error("存档失败:", e);
177	    StateManager.addMessage("⚠️ 存档失败: " + e.message, "danger");
178	    return false;
179	  }
180	}
181	
182	/** 自动存档 */
183	function autoSave() {
184	  try {
185	    const state = StateManager.getState();
186	    const saveData = JSON.parse(JSON.stringify(state));
187	    saveData.lastPlayedAt = Date.now();
188	    if (saveData.messageLog && saveData.messageLog.length > 200) {
189	      saveData.messageLog = saveData.messageLog.slice(-200);
190	    }
191	    localStorage.setItem(AUTO_SAVE_KEY, JSON.stringify(saveData));
192	
193	    // 更新索引中的自动存档信息
194	    const index = getSaveIndex();
195	    index._auto = {
196	      day: state.player.day,
197	      phase: state.player.phase,
198	      cash: state.resources.cash,
199	      age: state.player.age,
200	      debt: state.resources.debt,
201	      totalEarned: state.resources.totalEarned,
202	      location: state.trade.currentLocation,
203	      rank: state.player.phase === "corporate" ? state.corporate.rank : null,
204	      savedAt: Date.now(),
205	      narrative: generateSaveNarrative(state),
206	    };
207	    setSaveIndex(index);
208	  } catch (e) {
209	    /* 静默 */
210	  }
211	}
212	
213	/** 从指定槽位加载存档 */
214	function loadGame(slot) {
215	  try {
216	    let key;
217	    if (slot === "_auto") {
218	      key = AUTO_SAVE_KEY;
219	    } else if (typeof slot === "number" && slot >= 1 && slot <= NUM_SLOTS) {
220	      key = slotKey(slot);
221	    } else {
222	      // 兼容旧版：尝试直接以 slot 为键
223	      key = slot;
224	    }
225	
226	    const json = localStorage.getItem(key);
227	    if (!json) return null;
228	    return JSON.parse(json);
229	  } catch (e) {
230	    console.error("读档失败:", e);
231	    return null;
232	  }
233	}
234	
235	/** 删除指定槽位的存档 */
236	function deleteSave(slot) {
237	  if (slot === "_auto") {
238	    localStorage.removeItem(AUTO_SAVE_KEY);
239	    const index = getSaveIndex();
240	    delete index._auto;
241	    setSaveIndex(index);
242	    return;
243	  }
244	  if (slot < 1 || slot > NUM_SLOTS) return;
245	  localStorage.removeItem(slotKey(slot));
246	  const index = getSaveIndex();
247	  delete index[slot];
248	  setSaveIndex(index);
249	}
250	
251	/** 检查指定槽位是否有存档 */
252	function hasSave(slot) {
253	  if (slot === "_auto") return localStorage.getItem(AUTO_SAVE_KEY) !== null;
254	  if (typeof slot === "number")
255	    return localStorage.getItem(slotKey(slot)) !== null;
256	  // 兼容检查任意存档
257	  const index = getSaveIndex();
258	  return Object.keys(index).length > 0;
259	}
260	
261	/** 获取存档槽位的显示信息 */
262	function getSlotInfo(slot) {
263	  if (slot === "_auto") {
264	    const index = getSaveIndex();
265	    const meta = index._auto;
266	    if (!meta) {
267	      const raw = localStorage.getItem(AUTO_SAVE_KEY);
268	      if (!raw) return null;
269	      try {
270	        const data = JSON.parse(raw);
271	        return {
272	          day: data.player?.day || 1,
273	          phase: data.player?.phase || "street",
274	          cash: data.resources?.cash || 0,
275	          age: data.player?.age || 20,
276	          debt: data.resources?.debt || 0,
277	          totalEarned: data.resources?.totalEarned || 0,
